overlays-alert-dialog--default.snippet:
import { Component } from '@angular/core';
import { AlertDialogComponent } from './alert-dialog.component';
import { ButtonDirective } from './button.directive';

@Component({
  selector: 'app-demo',
  imports: [AlertDialogComponent, ButtonDirective],
  template: `
    <button
        appButton
        variant="outline"
        (click)="open = true">
        Open alert dialog
    </button>
    <app-alert-dialog
        [heading]="heading"
        [description]="description"
        [confirmLabel]="confirmLabel"
        [cancelLabel]="cancelLabel"
        [(open)]="open"
        (confirm)="result = 'Confirmed'"
        (cancelled)="result = 'Cancelled'" />
    <p class="mt-4 text-sm">Result: {{ result || 'none' }}</p>`,
})
export class DemoComponent {
  heading = 'Cancel this appointment?';
  description = 'This action cannot be undone. The slot will be released to other patients.';
  confirmLabel = 'Continue';
  cancelLabel = 'Cancel';
  cancelled(event: unknown) {}
  confirm(event: unknown) {}
  openChange(event: unknown) {}
}

